//! 🧪️ Root native allocator custody creates and drains actual canonical source fixtures.
use semio_framework_value_retirement::RetireOwned;
use semio_framework_value_clone_source::{RetainedCloneSource,RetainedCloneGrant};
pub struct FixtureSource<T:RetireOwned+Sync>(RetainedCloneSource<T>);
impl<T:RetireOwned+Sync> std::ops::Deref for FixtureSource<T>{type Target=RetainedCloneSource<T>;fn deref(&self)->&Self::Target{&self.0}}
impl<T:RetireOwned+Sync> FixtureSource<T>{fn drain(&mut self){for _ in 0..100000{if self.0.terminal_is_empty(){return;}let copy=self.0.next_close_copy_byte_demand().unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:self.0.next_close_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:self.0.next_close_release_byte_demand().unwrap(),maximum_depth:self.0.next_close_depth_demand().unwrap()};let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||self.0.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}panic!("original source fixture did not physically close");}}
impl<T:RetireOwned+Sync> Drop for FixtureSource<T>{fn drop(&mut self){if !std::thread::panicking(){self.drain();}}}
pub trait FixtureSourceBirth<T:RetireOwned+Sync>{fn from_owner(owner:T)->FixtureSource<T>;}
impl<T:RetireOwned+Sync> FixtureSourceBirth<T> for RetainedCloneSource<T>{fn from_owner(owner:T)->FixtureSource<T>{let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:Self::constructor_copy_bytes(),maximum_capacity_bytes:Self::owned_constructor_capacity_bytes::<()>(),maximum_depth:1,..Default::default()};FixtureSource(Self::admit_owned(owner,(),grant).unwrap_or_else(|_|panic!("original fixture source admission")).0)}}
